From 2bb24528be21c75ce6cc83ac9e7933af2ab944a8 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:45:29 +0100
Subject: [PATCH] applets/taskmanager: make wrapping around when scrolling
 optional

Scrolling over the task manager always jumped from the last task back to
the first one and vice versa, so it was easy to overshoot the wanted one.
Add a "Wrap around" option, enabled by default, to stop at either end.

BUG: 404781
---
 applets/taskmanager/main.xml               |  4 ++++
 applets/taskmanager/qml/ConfigBehavior.qml |  9 +++++++++
 applets/taskmanager/qml/MouseHandler.qml   |  2 +-
 applets/taskmanager/qml/code/TaskTools.js  | 14 +++++++++-----
 4 files changed, 23 insertions(+), 6 deletions(-)

diff --git a/applets/taskmanager/main.xml b/applets/taskmanager/main.xml
index 8c3b68785b..5789f8cfc9 100644
--- a/applets/taskmanager/main.xml
+++ b/applets/taskmanager/main.xml
@@ -98,6 +98,10 @@
       <label>Whether to skip minimized tasks when switching between them using the mouse wheel.</label>
       <default>true</default>
     </entry>
+    <entry name="wheelWrapAround" type="Bool">
+      <label>Whether to wrap around from the last task to the first one (and vice versa) when switching between them using the mouse wheel.</label>
+      <default>true</default>
+    </entry>
     <entry name="highlightWindows" type="Bool">
       <label>Whether to request the window manager highlight windows when hovering corresponding task tooltips.</label>
       <default>false</default>
diff --git a/applets/taskmanager/qml/ConfigBehavior.qml b/applets/taskmanager/qml/ConfigBehavior.qml
index bd4b7cf008..30f5e2281d 100644
--- a/applets/taskmanager/qml/ConfigBehavior.qml
+++ b/applets/taskmanager/qml/ConfigBehavior.qml
@@ -29,6 +29,7 @@ KCMUtils.SimpleKCM {
     property alias cfg_middleClickAction: middleClickAction.currentIndex
     property alias cfg_wheelEnabled: wheelEnabled.currentIndex
     property alias cfg_wheelSkipMinimized: wheelSkipMinimized.checked
+    property alias cfg_wheelWrapAround: wheelWrapAround.checked
     property alias cfg_showOnlyCurrentScreen: showOnlyCurrentScreen.checked
     property alias cfg_showOnlyCurrentDesktop: showOnlyCurrentDesktop.checked
     property alias cfg_showOnlyCurrentActivity: showOnlyCurrentActivity.checked
@@ -223,6 +224,14 @@ KCMUtils.SimpleKCM {
             enabled: wheelEnabled.currentIndex !== 0 // None
         }

+        QQC2.CheckBox {
+            id: wheelWrapAround
+            leftPadding: mirrored ? 0 : (wheelEnabled.indicator.width + wheelEnabled.spacing)
+            rightPadding: mirrored ? (wheelEnabled.indicator.width + wheelEnabled.spacing) : 0
+            text: i18nc("@option:check mouse wheel task cycling", "Wrap around")
+            enabled: wheelEnabled.currentIndex === 1 || wheelEnabled.currentIndex === 2 // AllTask, TaskOnly
+        }
+
         Item {
             Kirigami.FormData.isSection: true
         }
diff --git a/applets/taskmanager/qml/MouseHandler.qml b/applets/taskmanager/qml/MouseHandler.qml
index 2fd85860c2..d859ef7fc8 100644
--- a/applets/taskmanager/qml/MouseHandler.qml
+++ b/applets/taskmanager/qml/MouseHandler.qml
@@ -198,7 +198,7 @@ DropArea {
             return;
             }
             while (increment !== 0) {
-                TaskManagerApplet.TaskTools.activateNextPrevTask(anchor, increment < 0, Plasmoid.configuration.wheelSkipMinimized, Plasmoid.configuration.wheelEnabled, tasks);
+                TaskManagerApplet.TaskTools.activateNextPrevTask(anchor, increment < 0, Plasmoid.configuration.wheelSkipMinimized, Plasmoid.configuration.wheelEnabled, Plasmoid.configuration.wheelWrapAround, tasks);
                 increment += (increment < 0) ? 1 : -1;
             }
         }
diff --git a/applets/taskmanager/qml/code/TaskTools.js b/applets/taskmanager/qml/code/TaskTools.js
index 8f8adadd6f..d03ed96c6b 100644
--- a/applets/taskmanager/qml/code/TaskTools.js
+++ b/applets/taskmanager/qml/code/TaskTools.js
@@ -13,7 +13,7 @@
 // Can't be `let`, or else QML counterpart won't be able to assign to it.
 var taskManagerInstanceCount = 0;

-function activateNextPrevTask(anchor, next, wheelSkipMinimized, wheelEnabled, tasks) {
+function activateNextPrevTask(anchor, next, wheelSkipMinimized, wheelEnabled, wheelWrapAround, tasks) {
     // FIXME TODO: Unnecessarily convoluted and costly; optimize.

     if (wheelEnabled === 2) { // TaskOnly
@@ -80,12 +80,16 @@ function activateNextPrevTask(anchor, next, wheelSkipMinimized, wheelEnabled, ta
     for (let i = 0; i < taskIndexList.length; ++i) {
         if (taskIndexList[i] === activeTaskIndex)
         {
-            if (next && i < (taskIndexList.length - 1)) {
-                target = taskIndexList[i + 1];
-            } else if (!next) {
+            if (next) {
+                if (i < (taskIndexList.length - 1)) {
+                    target = taskIndexList[i + 1];
+                } else if (!wheelWrapAround) {
+                    target = taskIndexList[i];
+                }
+            } else {
                 if (i) {
                     target = taskIndexList[i - 1];
-                } else {
+                } else if (wheelWrapAround) {
                     target = taskIndexList[taskIndexList.length - 1];
                 }
             }
-- 
